function getYear() {
	var p = document._dir;

let currentDate = new Date();
var ngayhld = p.valForm('ngay_hld');
//console.log(ngayhld)
// Cộng thêm 10 năm
let newDate = new Date(currentDate);
newDate.setFullYear(currentDate.getFullYear() + 10);

var formatDate = newDate.toLocaleDateString('en-GB');
document.querySelector("input.ngay_hld").setAttribute('value', formatDate);

//console.log(dateYear)


// Hiển thị ngày mới nhất cộng thêm 10 năm
console.log("Ngày mới nhất cộng thêm 10 năm: " + newDate.toISOString().slice(0, 10));
}
